namespace Juspay {
     using Newtonsoft.Json;
     using System.Net;
     using System.Net.Http;
     using System;
     public class RequestOptions {

      public RequestOptions() {
         this.JuspayJWT = JuspayEnvironment.Instance.JuspayJWT;
         this.MerchantId = JuspayEnvironment.Instance.MerchantId;
      }
      public RequestOptions(string merchantId, string apiKey, SecurityProtocolType? ssl, long? readTimeoutInMilliSeconds, IJuspayJWT juspayJWT = null) {
         if (merchantId != null) this.MerchantId = merchantId;
         else this.MerchantId = JuspayEnvironment.Instance.MerchantId;
         if (apiKey != null) this.ApiKey = apiKey;
         if (ssl.HasValue) this.SSL = ssl.Value;
         if (readTimeoutInMilliSeconds.HasValue) this.ReadTimeoutInMilliSeconds = readTimeoutInMilliSeconds.Value;
         if (juspayJWT != null) this.juspayJWT = juspayJWT;
         else this.juspayJWT = JuspayEnvironment.Instance.JuspayJWT;
      }
         private string merchantId;

         [JsonProperty("x-merchantid")]
        public string MerchantId { get { return this.merchantId; } set {
         if (value == null) this.merchantId = JuspayEnvironment.Instance.MerchantId;
         else this.merchantId = value;
        } }
        public string ApiKey { get; set; }
        public SecurityProtocolType SSL { get; set; }
        private TimeSpan readTimeout; 
        public long ReadTimeoutInMilliSeconds {
            get => readTimeout.Milliseconds;
            set => readTimeout = TimeSpan.FromTicks(value);
         }

         public TimeSpan ReadTimeout {
            get => readTimeout;
            set => readTimeout = value;
         }

         private IJuspayJWT juspayJWT;
         public IJuspayJWT JuspayJWT { get { return this.juspayJWT; } set {
            if(value == null) this.juspayJWT = JuspayEnvironment.Instance.JuspayJWT;
            else this.juspayJWT = value;
         } }
         [JsonProperty("x-customerid")]
         public string CustomerId { get; set; }
        public override string ToString()
        {
           return JsonConvert.SerializeObject(
                this,
                Formatting.Indented);
        }
     }
}

namespace Juspay
{
    using System;
    using System.Collections.Generic;
    using System.Net.Http;
    using System.Text;

    public enum ContentType
    {
        FormUrlEncoded,
        Json
    }

    /// <summary>
    /// Represents a request to Juspay's API.
    /// </summary>
    public class JuspayRequest
    {
        public object Input;

        public object QueryParams { get; set; }

        public string Path { get; set; }

        public ContentType ContentType { get; set; }

        public HttpMethod Method { get; set; }

        public RequestOptions RequestOptions { get; }

        public string ApiKey { get; }

        public string ApiBase { get; set; }

        public bool IsJwtSupported { get; set; }

        public JuspayRequest(HttpMethod method, string path, object input, object queryParams, RequestOptions requestOptions, ContentType contentType, string apiKey, string baseUrl, bool isJWTSupported)
        {
            this.RequestOptions = requestOptions;

            this.Method = method;

            this.Path = path;

            this.QueryParams = queryParams;

            this.ContentType = contentType;

            this.ApiKey = apiKey;

            this.ApiBase = baseUrl;

            this.Input = input;

            this.IsJwtSupported = isJWTSupported;

            if (requestOptions == null) this.RequestOptions = new RequestOptions();
            else this.RequestOptions = requestOptions;

            if (RequestOptions.ApiKey != null) this.ApiKey = requestOptions.ApiKey;
            else this.ApiKey = apiKey;
        }


        public override string ToString()
        {
            return string.Format(
                "<{0} Method={1} Uri={2} ContentType={3} RequestOptions={4}>",
                this.GetType().FullName,
                this.Method,
                this.ApiBase + this.Path,
                this.ContentType,
                this.RequestOptions.ToString()
                );
        }

    }
}

namespace Juspay
{
    using System;
    using System.Collections.Generic;

    public class JuspayException : Exception
    {
        public JuspayException(string message)
            : base(message)
        {
            JuspayEnvironment.Instance.log.Error(message);
        }

        public JuspayException(string message, Exception err)
            : base(message, err)
        {
            JuspayEnvironment.Instance.SerializedLog(new Dictionary<string, string> { {"message", message}, { "error", err.ToString() } }, JuspayEnvironment.JuspayLogLevel.Error);
        }

        public JuspayException(int httpStatusCode, JuspayError JuspayError, JuspayResponse juspayResponse, string message)
            : base(message)
        {
            this.HttpStatusCode = httpStatusCode;
            this.JuspayError = JuspayError;
            this.JuspayResponse = juspayResponse;
            JuspayEnvironment.Instance.SerializedLog(new Dictionary<string, string> { {"message", message}, { "error", JuspayError?.ToString() }, { "juspay_response", JuspayResponse.RawContent }, { "http_status_code", httpStatusCode.ToString() } }, JuspayEnvironment.JuspayLogLevel.Error);
        }

        public int HttpStatusCode { get; set; }

        public JuspayError JuspayError { get; set; }

        public JuspayResponse JuspayResponse { get; set; }
    }

    public class AuthorizationException : JuspayException
    {
        public AuthorizationException(int httpStatusCode, JuspayError Error, JuspayResponse juspayResponse) : base(httpStatusCode, Error, juspayResponse, "AUTHORIZATION ERROR") {}
    }

    public class AuthenticationException : JuspayException
    {
        public AuthenticationException(int httpStatusCode, JuspayError Error, JuspayResponse juspayResponse) : base(httpStatusCode, Error, juspayResponse, "AUTHENTICATION ERROR check your API KEY") {}
    }

    public class InvalidRequestException : JuspayException
    {
        public InvalidRequestException(int httpStatusCode, JuspayError Error, JuspayResponse juspayResponse) : base(httpStatusCode, Error, juspayResponse, "INVALID REQUEST") {}
    }

    public class ValidationException : JuspayException
    {
        public ValidationException(string message) : base(message) {}
    }

    public class JWTException : JuspayException
    {
        public JWTException(string message) : base(message) {}  
    }

    public class JWKException : JuspayException
    {
        public JWKException(string message) : base(message) {}
    }

    public class JWEException : JuspayException
    {
        public JWEException(string message) : base(message) {}
    }

    public class JWSException : JuspayException
    {
        public JWSException(string message) : base(message) {}
    }

}

[assembly: log4net.Config.XmlConfigurator(ConfigFile = "log4net.config")]
namespace Juspay {
    using System;
    using System.Reflection;
    using Newtonsoft.Json;
    using System.Net;
    using log4net;
    using log4net.Core;
    using log4net.Repository.Hierarchy;
    using System.Threading;

    public class JuspayEnvironment {

        private JuspayEnvironment() {
            juspayClient = new Lazy<IJuspayClient>(() => BuildDefaultJuspayClient());
            SSL = DEFAULT_SSL_PROTOCOL;
            juspaySDKVersion  = getJupaySDKVersion();
        }

        private static readonly Lazy<JuspayEnvironment> juspayEnvInstance = new Lazy<JuspayEnvironment>(() => new JuspayEnvironment());

        public static JuspayEnvironment Instance => juspayEnvInstance.Value;

        #if  NETCOREAPP3_0_OR_GREATER || NET47_OR_GREATER
            public readonly SecurityProtocolType DEFAULT_SSL_PROTOCOL = SecurityProtocolType.SystemDefault;
        #else
            public readonly SecurityProtocolType DEFAULT_SSL_PROTOCOL = SecurityProtocolType.Ssl3 | SecurityProtocolType.Tls | SecurityProtocolType.Tls11 | SecurityProtocolType.Tls12;
        #endif
        public SecurityProtocolType SSL { get; set; }
        public readonly string juspaySDKVersion;
        public string BaseUrl { get; set; }
        public string ApiKey { get; set; }
        public string MerchantId { get; set; }
        public long ConnectTimeoutInMilliSeconds {
            get => connectTimeoutInMilliSeconds.Milliseconds;
            set => connectTimeoutInMilliSeconds = TimeSpan.FromTicks(value);
        }
        public long ReadTimeoutInMilliSeconds { 
            get => readTimeoutInMilliSeconds.Milliseconds;
            set => readTimeoutInMilliSeconds = TimeSpan.FromTicks(value);
        }

        public readonly ILog log = LogManager.GetLogger(MethodBase.GetCurrentMethod().DeclaringType);
        public enum JuspayLogLevel
        {
            All,
            Debug,
            Error,
            Info,
            Off,
        }

        public void SerializedLog(object message, JuspayLogLevel level)
        {
            string jMessage = JsonConvert.SerializeObject(message);
            switch (level) 
            {
                case JuspayLogLevel.Debug:
                    log.Debug(jMessage);
                    break;
                case JuspayLogLevel.Error:
                    log.Error(jMessage);
                    break;
                default:
                    log.Info(jMessage);
                    break;
            }
        }
        public void SetLogLevel(JuspayLogLevel level)
        {
            Level logLevel;

            switch (level)
            {
                case JuspayLogLevel.All:
                    logLevel = Level.All;
                    break;
                case JuspayLogLevel.Debug:
                    logLevel = Level.Debug;
                    break;
                case JuspayLogLevel.Error:
                    logLevel = Level.Error;
                    break;
                case JuspayLogLevel.Info:
                    logLevel = Level.Info;
                    break;
                case JuspayLogLevel.Off:
                    logLevel = Level.Off;
                    break;
                default:
                    logLevel = Level.All;
                    break;
            }
            ((Hierarchy)LogManager.GetRepository()).Root.Level = logLevel;
        }

        public bool SetLogFile(string filePath)
        { 
            log4net.Repository.ILoggerRepository RootRep = log.Logger.Repository;
            foreach (log4net.Appender.IAppender iApp in RootRep.GetAppenders())
            {
                if (iApp.Name.ToString() == "FileAppender")
                {
                    log4net.Appender.FileAppender fApp = (log4net.Appender.FileAppender)iApp;
                    fApp.File = filePath;
                    fApp.ActivateOptions();
                    return true;
                }
            }
             return false;
        }

        public IJuspayJWT JuspayJWT { get; set; }
        private TimeSpan connectTimeoutInMilliSeconds;
        private TimeSpan readTimeoutInMilliSeconds;
        private Lazy<IJuspayClient> juspayClient;
        private string getJupaySDKVersion() {
            var assemblyName = typeof(JuspayEnvironment).GetTypeInfo().Assembly.FullName;
            if (assemblyName != null) {
                return new AssemblyName(assemblyName)?.Version?.ToString(3);
            }
            return null;
        }

        public IJuspayClient JuspayClient {
            get => juspayClient.Value;
            set => juspayClient = new Lazy<IJuspayClient>(() => value);
        }
        public JuspayClient BuildDefaultJuspayClient()
        {
            if (ApiKey != null && ApiKey.Length == 0)
            {
                throw new JuspayException("INVALID_API_KEY");
            }
            IHttpClient httpClient = new SystemHttpClient(connectTimeoutInMilliSeconds, readTimeoutInMilliSeconds);
            return new JuspayClient(httpClient);
        }

    }
